// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"ja","term":"エアドロップ","aka":["Airdrop","エアドロ"],"short":"エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。","body":["配布の目的は、ユーザーの獲得、初期の利用者への還元、ガバナンス権の分散などです。過去に特定のプロトコルを使った、一定量のトークンを保有していた、テストネットに参加したといった条件で対象者が決まることが多く、条件が配布時に初めて公表されるケースもあります。",["受け取るには「請求（クレーム）」の手続きが必要な場合があり、その際に",["ガス代","gas-fee"],"がかかります。配布直後は多くの受取人が売りに出すため、価格が大きく変動しやすい点も知っておきましょう。税制上の扱いは国によって異なります。"],["エアドロップを装った詐欺も非常に多いです。SNSやDMで届く「無料トークンを受け取る」リンクや、",["ウォレット","crypto-wallet"],"に勝手に送られてきた見覚えのないトークンには要注意です。請求サイトで",["シードフレーズ","seed-phrase"],"の入力や無制限の承認を求められたら、詐欺だと考えてください。"]],"example":["例えば、あるプロトコルが利用者1人あたり500トークンを配布し、",["上場","token-listing"],"直後の価格が1トークン0.8ドルだったとします。評価額は400ドルですが、クレームにガス代が5ドルかかり、受取人の売りで価格が0.5ドルまで下がると、手取りの評価額は250 − 5 = 245ドルになります。"],"mistakes":["「エアドロップ受け取り」をうたうサイトでシードフレーズを入力すること。","ウォレットに届いた見知らぬトークンを売ろうとして、悪意あるコントラクトを承認すること。","エアドロップ目当てに、実態の分からないプロトコルへ大きな資金を預けること。"],"faq":[{"q":"エアドロップは本当に無料ですか？","a":"トークン自体は無料で配られますが、受け取りにガス代がかかる場合があります。受け取りの前にお金を送るよう求められたら、詐欺を疑いましょう。"},{"q":"勝手に送られてきたトークンはどうすればいいですか？","a":"触らずに放置するのが基本です。売却や送金のために見知らぬサイトでウォレットを接続すると、資産を抜き取られるおそれがあります。"}],"title":"エアドロップとは？仕組みと詐欺の見分け方","description":"エアドロップの意味と配布の仕組み、受け取り時のガス代、エアドロップ詐欺を見分けるポイントを解説します。","related":[["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["token-approval","トークン承認（Approve・アローワンス）","トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。"],["governance-token","ガバナンストークン","ガバナンストークンとは、DeFiやDAOなどのプロジェクトで、運営方針や仕様変更に関する投票に参加する権利を表すトークンです。"],["launchpool","ローンチプール（Launchpool）","ローンチプールとは、取引所が指定した暗号資産やステーブルコインを一定期間預け入れると、新しく上場するトークンを報酬として受け取れる取引所のキャンペーン型サービスです。"],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"ja","term":"中央集権型取引所（CEX）","aka":["CEX","中央集権取引所","Centralized exchange"],"short":"中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。","body":[["バイナンス、OKX、Bybit、Bitget、コインベースなどの大手取引所や、日本国内の登録業者の多くがCEXです。利用者は口座を開設して",["本人確認","kyc"],"（KYC）を済ませ、法定通貨や",["暗号資産","cryptocurrency"],"を入金し、取引所内の",["板（オーダーブック）","order-book"],"で売買します。"],["CEXの利点は、操作が簡単で",["流動性","liquidity"],"が高く、",["現物取引","spot-trading"],"だけでなく先物、",["ステーキング","staking"],"、コピートレードなど多様なサービスを1つの口座で使えることです。パスワードを忘れても、本人確認を通じてアカウントを復旧できます。"],"一方で、資産の管理を取引所に任せるため、取引所の破綻、ハッキング、出金停止のリスクがあります。準備金証明（プルーフ・オブ・リザーブ）の公開状況や、運営会社の規制・登録状況を確認しましょう。利用できるサービスやレバレッジの上限は、居住国の規制によって異なります。"],"example":"例えば、CEXで10万円分のETHを現物で買い、取引手数料が0.1%なら手数料は100円です。その後、自分のウォレットへ出金すると、取引所が定める出金手数料が別にかかります。出金手数料が0.002 ETHで1 ETH = 50万円なら1,000円となり、手数料の合計は1,100円、購入額の1.1%になります。","mistakes":["取引手数料だけを比べ、出金手数料やスプレッドのコストを見落とすこと。","長期保有する資産をすべて1つの取引所に置いたままにすること。","2段階認証を設定せずに取引所のアカウントを使うこと。"],"faq":[{"q":"CEXとDEXの違いは何ですか？","a":"CEXは運営会社が資産を預かって取引を仲介し、DEXはスマートコントラクトで取引を行い、利用者が自分のウォレットで資産を管理します。"},{"q":"CEXに資産を置いておくのは安全ですか？","a":"大手取引所はセキュリティ対策を講じていますが、破綻やハッキングのリスクはゼロではありません。長期保有分は自己管理も検討しましょう。"}],"title":"中央集権型取引所（CEX）とは？仕組みとDEXとの違い","description":"中央集権型取引所（CEX）の仕組み、メリットとリスク、DEXとの違い、手数料の見方を初心者向けに解説します。","related":[["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。"],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"ja","term":"サポートライン・レジスタンスライン（支持線・抵抗線）","aka":["サポート","レジスタンス","支持線","抵抗線"],"short":"サポートライン・レジスタンスラインとは、過去に下落が止まりやすかった価格帯（支持線）と、上昇が止まりやすかった価格帯（抵抗線）をチャート上に示したものです。","body":["サポートは、その付近で買い注文が集まりやすく、価格が下げ止まってきた水準です。レジスタンスは、売り注文が出やすく、上値が抑えられてきた水準です。過去の安値や高値、何度も反発した価格帯、キリのいい数字（例えば60,000や100,000）が意識されやすくなります。","これらは1本の線というより「帯」として考えるのが実用的です。参加者がまったく同じ価格で動くわけではないため、少し突き抜けてから戻ることもよくあります。また、強いレジスタンスを上に抜けると、その価格帯が今度はサポートとして機能することがあり、これを役割の転換と呼びます。",["トレードでは、サポートのやや下に",["逆指値","stop-loss"],"（損切り）を置く、レジスタンスの手前で利益確定する、といった計画づくりに使います。ただし多くの人が同じ場所に損切りを置くため、その水準を一時的に割り込むと連鎖的に注文が発動し、値動きが大きくなることがあります。"]],"example":"ETHが過去2か月で2,800 USDT付近まで3回下げて、そのたびに反発しているとします。この帯をサポートと見て2,850 USDTで買い、損切りをサポートの少し下の2,760 USDTに置けば、1 ETHあたりの想定損失は90 USDTです。上の3,100 USDT付近が何度も跳ね返された高値なら、そこをレジスタンスとして利益確定の目安にでき、想定利益は250 USDTになります。","mistakes":["サポートラインをぴったり1つの価格だと考え、損切りを線のすぐ下に置いて小さなヒゲで刈られる。","一度割り込んだサポートが、その後も同じように支えてくれると考えて買い増しを続ける。","短い時間足で引いた線と日足や週足で引いた線を同じ重みで扱う。"],"faq":[{"q":"サポートラインはどうやって引けばよいですか？","a":"過去に何度も下げ止まった安値同士を結ぶか、その価格帯に水平な帯を引くのが基本です。反発した回数が多く、時間足が長いほど意識されやすくなります。"},{"q":"レジスタンスを抜けたら必ず上がりますか？","a":"必ずではありません。抜けた直後に戻される「だまし」もよくあるため、出来高や終値での確定を確認する人が多いです。"}],"title":"サポートライン・レジスタンスラインとは？引き方と使い方","description":"サポートライン（支持線）とレジスタンスライン（抵抗線）の意味、引き方、役割の転換、損切りや利確の計画への使い方を解説します。","related":[["candlestick-chart","ローソク足チャート","ローソク足チャートとは、一定期間の始値・高値・安値・終値の4つの価格を、1本のローソクの形で表した価格チャートのことです。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["all-time-high","史上最高値（ATH）","史上最高値（ATH）とは、ある暗号資産がこれまでに記録した中で最も高い価格のことで、英語のAll-Time Highの略です。"]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"一本のローソク足：何が分かる四つの情報なのか？"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"ja","term":"ドルコスト平均法（DCA）","aka":["DCA","積立投資","定額積立","dollar-cost averaging"],"short":"ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。","body":[["毎週や毎月など決まった間隔で、同じ金額分の",["暗号資産","cryptocurrency"],"を買います。価格が高いときは少ない数量、安いときは多い数量を買うことになるため、平均取得単価がならされます。いつ買うべきかを毎回判断しなくてよいので、相場を見て迷ったり、高値でまとめて買ってしまったりするのを防ぎやすくなります。"],"注意したいのは、ドルコスト平均法は損をしない方法ではないという点です。価格が長期的に下がり続ければ、積み立てた資産も評価損になります。また、一括で買った場合と比べて有利か不利かは、その後の値動きによって変わります。",["多くの取引所には、指定した金額・頻度で自動購入する積立機能があります。取引所によって手数料や対応銘柄、",["販売所","instant-convert"],"形式か取引所形式かが異なるため、少額を頻繁に買う場合は1回あたりのコストを確認してください。"]],"example":["毎月1万円分のBTCを4か月買うとします。1か月目のBTC価格が1,000万円なら0.001 ",["BTC","bitcoin"],"、2か月目が800万円なら0.00125 BTC、3か月目が500万円なら0.002 BTC、4か月目が1,000万円なら0.001 BTCを買えます。合計4万円で0.00525 BTCとなり、平均取得単価は4万÷0.00525で約762万円です。4か月目の価格1,000万円で評価すると5.25万円になります。"],"mistakes":["ドルコスト平均法なら元本割れしないと思い込む。","下落時に不安になって積立を止め、安い価格で買えるはずだった期間を逃す。","少額を毎日買う設定にして、スプレッドや手数料が積み重なり実質的なコストが高くなる。"],"faq":[{"q":"ドルコスト平均法と一括投資はどちらが有利ですか？","a":"その後の値動き次第で、どちらが有利かは一概に言えません。ドルコスト平均法は購入タイミングの判断を減らし、高値づかみのリスクを分散する方法です。"},{"q":"積立の頻度は毎日と毎月のどちらがよいですか？","a":"頻度による差は値動き次第ですが、回数が増えるほど手数料やスプレッドの合計が増えます。自分の資金計画と1回あたりのコストで決めるのが現実的です。"}],"title":"ドルコスト平均法（DCA）とは？暗号資産の積立の仕組み","description":"ドルコスト平均法（DCA）の仕組み、平均取得単価の計算方法、一括投資との違い、積立でよくある失敗を暗号資産の例で解説します。","related":[["hodl","HODL（ガチホ）","HODL（ガチホ）とは、価格の上下に関係なく暗号資産を売らずに長期保有し続ける投資スタイルのことで、日本では「ガチホ」とも呼ばれます。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"],["grid-trading-bot","グリッドトレードボット","グリッドトレードボットとは、設定した価格帯をいくつかの網目（グリッド）に分け、価格が下がれば買い、上がれば売る指値注文を自動で繰り返す取引ツールのことです。"],["spot-trading","現物取引（スポット取引）","現物取引（スポット取引）とは、暗号資産をその時点の価格で実際に売買し、買った資産をそのまま受け取って保有する取引のことです。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"いくら買うか決める前に、いくら失えるかを決めよ"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"ja","term":"USDT建て先物（リニア先物）","aka":["USDT建て","リニア先物","USDT-M","USDTマージン先物"],"short":"USDT建て先物（リニア先物）とは、証拠金と損益をステーブルコインのUSDTで計算する先物契約で、価格の変化と損益が比例するためわかりやすいのが特徴です。","body":["USDT建て先物では、BTCの契約でもETHの契約でも、証拠金はUSDTで差し入れ、損益もUSDTで受け取ります。契約サイズはBTCなどのコイン枚数で決められ、損益は（決済価格−建値）×数量というシンプルな式で計算できます。価格と損益が直線的に比例するため「リニア」と呼ばれます。",["大きな利点は、1つのUSDT残高で多くの銘柄の先物を取引できることです。",["クロスマージン","cross-margin"],"を使えば、複数のポジションで同じ証拠金を共有できます。また、証拠金が",["ステーブルコイン","stablecoin"],"なので、取引しているコインの値下がりで証拠金自体の価値が減ることはありません。"],"一方で、証拠金のUSDTはTether社が発行するステーブルコインであり、その発行体のリスクは残ります。取引所によってはUSDCを証拠金にする契約もあります。どの資産で証拠金を持つかは取引所ごとの仕様を確認してください。"],"example":["ETHが3,200 USDTのとき、USDT建て先物で2 ETHを",["ロング","long-and-short"],"し、証拠金640 ",["USDT","usdt"],"（10倍）を入れたとします。ETHが3,360 USDTに上がって決済すると、利益は（3,360−3,200）×2＝320 USDTです。ETHが3,040 USDTに下がれば損失は320 USDTで、証拠金の半分になります。どちらも価格の変化幅に数量を掛けるだけで計算できます。"],"mistakes":["契約数量がコイン枚数なのか契約単位なのかを確認せず、思っていた10倍のポジションを建ててしまう。","クロスマージンで複数の銘柄を持ち、1つの損失が全体の証拠金を減らすことを意識しない。","証拠金がUSDTならリスクがないと考え、レバレッジによる損失を軽く見る。"],"faq":[{"q":"USDT建て先物の損益はどう計算しますか？","a":"ロングなら（決済価格−建値）×数量、ショートなら（建値−決済価格）×数量で、結果はUSDTで表されます。手数料と資金調達率は別にかかります。"},{"q":"USDT建てとUSDC建ての違いは？","a":"証拠金と損益に使うステーブルコインが違います。取引所によって対応銘柄や手数料が異なるため、契約仕様で確認してください。"}],"title":"USDT建て先物（リニア先物）とは？特徴と計算方法","description":"USDT建て先物（リニア先物）の仕組み、損益の計算方法、コイン建て先物との違い、クロスマージンでの注意点を具体例で解説します。","related":[["coin-margined-futures","コイン建て先物（インバース先物）","コイン建て先物（インバース先物）とは、証拠金と損益をUSDTではなくBTCやETHなどのコインそのもので受け渡す先物契約で、契約サイズは米ドル建てで表されるのが一般的です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["usdt","USDT（テザー）","USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。"],["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"ja","term":"建玉（未決済建玉・オープンインタレスト）","aka":["未決済建玉","オープンインタレスト","OI","open interest"],"short":"建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。","body":[["先物の契約には必ず買い手と売り手がいるため、",["ロング","long-and-short"],"1枚にはショート1枚が対応します。建玉は、そのペアの数を数えたものです。新規の買い手と新規の売り手が約定すれば建玉は増え、両者がともに決済すれば減ります。一方が新規で他方が決済なら、持ち主が入れ替わるだけで建玉は変わりません。"],[["取引量","trading-volume"],"は一定期間の売買の量を表し、建玉はある時点で残っているポジションの量を表します。価格の上昇とともに建玉が増えていれば、新しい資金がポジションを建てていると読めます。価格が上がっているのに建玉が減っていれば、ショートの買い戻し（決済）が中心と読めます。"],["建玉が急に大きく膨らんだ状態は、",["レバレッジ","leverage"],"がかかったポジションが多いことを意味し、急変時に大量の清算が起きやすくなります。建玉は取引所ごとの値と、複数取引所の合計値があり、枚数ベースとドル建てで表示が違うため、比べるときは単位をそろえてください。"]],"example":["ある時点でBTC",["無期限先物","perpetual-futures"],"の建玉が50,000 BTCだとします。新規にロングしたい人Aと新規にショートしたい人Bが1 BTC分約定すると、建玉は50,001 BTCになります。その後、Aが持っていたロングを、新規にロングしたい人Cに売って決済すれば、建玉は50,001 BTCのままです。最後にCとBがともに決済すれば、建玉は50,000 BTCに戻ります。"],"mistakes":["建玉と取引量を同じものだと考え、取引が多い日は建玉も多いと思い込む。","建玉が増えたことだけで、価格が上がると判断する。","枚数ベースの建玉とドル建ての建玉を比べ、価格変動による見かけの増減を誤解する。"],"faq":[{"q":"建玉が増えると価格は上がりますか？","a":"建玉の増加はロングとショートの両方が同時に増えていることを示すだけで、価格の方向は決まりません。価格の動きとあわせて読む必要があります。"},{"q":"建玉と取引量の違いは何ですか？","a":"取引量は一定期間に売買された量、建玉はある時点で決済されずに残っているポジションの量です。"}],"title":"建玉（オープンインタレスト）とは？意味と読み方","description":"先物の建玉（未決済建玉・オープンインタレスト）の意味、増減の仕組み、取引量との違い、価格と組み合わせた読み方を解説します。","related":[["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["long-short-ratio","ロングショート比率","ロングショート比率とは、先物市場でロング（買い）を持っている口座やポジションと、ショート（売り）を持っているものの割合を比べた指標で、市場参加者の偏りを見るのに使われます。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"ja","term":"ホットウォレット","aka":["hot wallet","オンラインウォレット"],"short":"ホットウォレットとは、インターネットに接続された状態で秘密鍵を扱う暗号資産ウォレットのことで、すぐに送金できる反面、オンライン攻撃の対象になりやすいものです。","body":[["スマホアプリの",["ウォレット","crypto-wallet"],"、ブラウザ拡張のウォレット、取引所の入出金用ウォレットなどがホットウォレットにあたります。",["秘密鍵","private-key"],"がネットにつながった端末上にあるため、数タップで送金やDeFiの操作ができます。"],["便利さの代償は、マルウェア、偽サイト、悪意ある",["トークン承認","token-approval"],"などの攻撃を受けやすい点です。端末が乗っ取られれば、秘密鍵ごと資産を抜かれる可能性があります。"],["そのため、日常的に使う少額だけをホットウォレットに置き、長期保有分は",["コールドウォレット","cold-wallet"],"に分ける運用が一般的です。財布と銀行口座の関係に近い考え方です。"]],"example":["合計で200万円分の",["暗号資産","cryptocurrency"],"を持っている人が、DeFiやNFTの売買に使う10万円分だけをブラウザ拡張のホットウォレットに入れ、残り190万円分を",["ハードウェアウォレット","hardware-wallet"],"に保管しているとします。偽サイトで誤って署名して被害に遭っても、失うのはホットウォレットの10万円分までに抑えられ、全体の5%で済みます。"],"mistakes":["長期保有する全資産をスマホのウォレット1つに入れっぱなしにすること。","検索広告やDMのリンクから開いたサイトにウォレットを接続すること。","端末のOSやウォレットアプリを更新せずに使い続けること。"],"faq":[{"q":"ホットウォレットとコールドウォレットの違いは何ですか？","a":"秘密鍵がオンライン環境にあるかどうかの違いです。ホットは便利で即時に使え、コールドはオフラインで保管するため遠隔攻撃に強いのが特徴です。"},{"q":"取引所の口座もホットウォレットですか？","a":"取引所は出金処理用にホットウォレットを使い、大部分をコールドウォレットで保管するのが一般的です。ただし利用者から見ると、鍵を取引所が持つカストディアル型である点が大きな違いです。"}],"title":"ホットウォレットとは？仕組みと安全な使い方","description":"ホットウォレットの意味、コールドウォレットとの違い、少額だけを置くなど安全に使うための具体的なポイントを解説します。","related":[["cold-wallet","コールドウォレット（コールドストレージ）","コールドウォレットとは、秘密鍵をインターネットから切り離した環境で保管する暗号資産の保管方法で、遠隔からのハッキングを受けにくいのが特徴です。"],["hardware-wallet","ハードウェアウォレット","ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。"],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"ja","term":"シードフレーズ（リカバリーフレーズ）","aka":["リカバリーフレーズ","ニーモニックフレーズ","復元フレーズ","seed phrase"],"short":"シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。","body":[["多くの",["ウォレット","crypto-wallet"],"はBIP39という規格に沿って、決められた2048語の単語リストからシードフレーズを生成します。この単語列から、ウォレット内の全",["アドレス","wallet-address"],"の",["秘密鍵","private-key"],"が計算されます。"],["つまり、シードフレーズを知っている人は誰でも、どの端末からでもあなたの資産を動かせます。正規のウォレット会社や取引所の",["サポート","support-and-resistance"],"が、シードフレーズを尋ねることはありません。尋ねてくる相手は詐欺だと判断してください。"],"保管は紙や金属プレートなどオフラインで行い、単語の順番も正確に記録します。写真、クラウド、メール、パスワード管理アプリへの保存は、漏洩の入口になりやすいため避けるのが基本です。"],"example":"12語のシードフレーズの場合、各単語は2048通りから選ばれるため、組み合わせは2048の12乗、つまりおよそ5.4かける10の39乗通りになります。総当たりで当てるのは現実的に不可能です。一方で、あなたが紙に書いた12語を他人が一度写真に撮るだけで、その人は数分で全資産を別アドレスへ送金できます。強さは数学ではなく保管方法で決まります。","mistakes":["シードフレーズをスマホのメモやスクリーンショットで保存すること。","「ウォレットの同期」や「エアドロップ受け取り」をうたうサイトに単語を入力すること。","単語の順番やスペルを確かめずに書き写すこと。"],"faq":[{"q":"シードフレーズを忘れたらどうなりますか？","a":"ウォレットが使える端末が残っていれば、すぐに資産を新しいウォレットへ移すべきです。端末も失った場合、誰にも復旧はできません。"},{"q":"シードフレーズと秘密鍵の違いは何ですか？","a":"秘密鍵は1つのアドレスを操作する鍵で、シードフレーズは複数の秘密鍵をまとめて生み出す元データです。シードフレーズの方が影響範囲が広くなります。"},{"q":"シードフレーズを複数に分けて保管してもよいですか？","a":"単純に半分ずつ分けると、片方が漏れただけで推測しやすくなる場合があります。分散保管するなら、同じ12語の完全なコピーを安全な2か所に置く方法が一般的です。"}],"title":"シードフレーズとは？意味と安全な保管方法","description":"シードフレーズ（リカバリーフレーズ）の意味、秘密鍵との関係、絶対に避けるべき保管方法と詐欺の手口をわかりやすく解説します。","related":[["private-key","秘密鍵（プライベートキー）","秘密鍵とは、暗号資産のアドレスから送金するための電子署名を作る秘密の数値で、これを持つ人がそのアドレスの資産を自由に動かせます。"],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["hardware-wallet","ハードウェアウォレット","ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"ja","term":"公開鍵（パブリックキー）","aka":["パブリックキー","public key"],"short":"公開鍵とは、秘密鍵から計算される暗号の鍵で、取引の署名が正しい秘密鍵で作られたかを誰でも検証できるようにするものです。","body":[["公開鍵暗号では、",["秘密鍵","private-key"],"と公開鍵がペアになります。秘密鍵から公開鍵は簡単に計算できますが、公開鍵から秘密鍵を逆算することは事実上できません。",["ビットコイン","bitcoin"],"や",["イーサリアム","ethereum"],"では楕円曲線暗号が使われています。"],["取引を送ると、ネットワークの",["ノード","node"],"は公開鍵を使って署名を検証します。これにより、秘密鍵を公開しなくても「この",["アドレス","wallet-address"],"の持ち主が承認した取引だ」と全員が確認できます。"],"ウォレットアドレスは、多くの場合、公開鍵をハッシュ関数で短く変換したものです。ふだん利用者が公開鍵を直接扱う場面は少なく、相手に伝えるのはアドレスの方です。"],"example":"イーサリアムでは、秘密鍵から64バイトの公開鍵が計算され、それをハッシュ化した結果の最後の20バイトがアドレスになります。20バイトは16進数で40文字なので、先頭の0xを含めて42文字のアドレスになります。あなたが友人に伝えるのはこの42文字のアドレスで、公開鍵も秘密鍵も伝える必要はありません。","mistakes":["公開鍵と秘密鍵の名前が似ているため、秘密鍵を「公開してよい鍵」と勘違いすること。","公開鍵とウォレットアドレスがまったく同じものだと思い込むこと。","拡張公開鍵（xpub）を気軽に共有し、全アドレスの残高や履歴を知られてしまうこと。"],"faq":[{"q":"公開鍵を他人に知られても大丈夫ですか？","a":"公開鍵から資産を動かすことはできません。ただし、拡張公開鍵などは関連する全アドレスを特定できるため、プライバシーの観点では慎重に扱いましょう。"},{"q":"公開鍵とアドレスの違いは何ですか？","a":"アドレスは多くの場合、公開鍵をハッシュ化して短くし、入力ミスを防ぐ仕組みを加えたものです。送金を受け取るときに使うのはアドレスです。"}],"title":"公開鍵とは？秘密鍵・アドレスとの違い","description":"暗号資産の公開鍵（パブリックキー）の意味、秘密鍵やウォレットアドレスとの関係、署名検証の仕組みを初心者向けに解説します。","related":[["private-key","秘密鍵（プライベートキー）","秘密鍵とは、暗号資産のアドレスから送金するための電子署名を作る秘密の数値で、これを持つ人がそのアドレスの資産を自由に動かせます。"],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"ja","term":"トランザクションハッシュ（TxID）","aka":["TxID","TxHash","取引ID","トランザクションID"],"short":"トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。","body":[["取引データをハッシュ関数にかけて得られる英数字の文字列で、",["イーサリアム","ethereum"],"なら0xで始まる66文字、",["ビットコイン","bitcoin"],"なら64文字の16進数です。同じTxIDを持つ別の取引は存在しません。"],["TxIDを",["ブロックエクスプローラー","block-explorer"],"で検索すると、送金元、送金先、金額、手数料、ブロックに取り込まれたか、何回の承認があるかを確認できます。送金した側も受け取る側も、同じ情報を見られます。"],["入金が反映されないとき、取引所の",["サポート","support-and-resistance"],"は必ずTxIDを求めます。出金履歴の画面からTxIDをコピーできるので、問い合わせの前に自分でもエクスプローラーで状態を確認しておくと解決が早くなります。"]],"example":["取引所Aから取引所Bへ0.05 BTCを出金して1時間たっても反映されないとします。Aの出金履歴からTxIDをコピーしてエクスプローラーで検索すると、状態は「承認済み」、",["承認数","block-confirmations"],"は2でした。Bが入金反映に3承認を求めている場合、あと1承認、ビットコインならおよそ10分前後待てば反映される見込みだと分かります。"],"mistakes":["TxIDではなくウォレットアドレスを検索して、取引の状態が分からないと慌てること。","違うチェーンのエクスプローラーでTxIDを検索して「見つからない」と判断すること。","送金先が詐欺サイトなのに、偽サポートにTxIDと一緒に秘密情報まで渡すこと。"],"faq":[{"q":"TxIDが表示されないのはなぜですか？","a":"取引所が出金をまだ処理中で、ブロックチェーンに送信していない段階だと考えられます。出金ステータスが「処理中」のうちは、TxIDが発行されないことがあります。"},{"q":"TxIDを他人に教えても大丈夫ですか？","a":"TxIDは公開情報なので、資産を盗まれることはありません。ただし、送受信したアドレスや金額が相手に分かる点は理解しておきましょう。"}],"title":"トランザクションハッシュ（TxID）とは？確認方法","description":"トランザクションハッシュ（TxID）の意味、ブロックエクスプローラーでの確認方法、入金が反映されないときの使い方を解説します。","related":[["block-explorer","ブロックエクスプローラー","ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。"],["block-confirmations","ブロック承認数（コンファメーション）","ブロック承認数とは、取引が含まれたブロックの後にいくつのブロックが積み重なったかを示す数で、多いほど取引が覆される可能性が低くなります。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["mempool","メンプール（Mempool）","メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"「送金完了」と出ているのに届かない。どこを調べるべき？"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"ja","term":"アドレスポイズニング","aka":["アドレス汚染","address poisoning","類似アドレス詐欺"],"short":"アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。","body":[["攻撃者は、あなたがよく送金する相手の",["アドレス","wallet-address"],"と先頭と末尾の数文字が同じ偽アドレスを作ります。そこからあなたのアドレスへ、ごく少額や0のトークンを送り、取引履歴に偽アドレスを紛れ込ませます。"],["多くの",["ウォレット","crypto-wallet"],"や取引所はアドレスを途中省略して表示するため、先頭と末尾だけを見て確認する習慣があると見抜けません。次回、履歴から送金先をコピーした瞬間に罠にかかります。"],["対策は、送金先を取引履歴からコピーしないこと、",["出金ホワイトリスト","withdrawal-whitelist"],"やアドレス帳に検証済みのアドレスを登録して使うこと、アドレス全体またはより長い範囲を照合することです。"]],"example":"あなたが毎月、取引所の入金アドレス「0x7a3F…9c1E」に2,000 USDTを送っているとします。ある日、履歴に「0x7a3F…9c1E」と表示される送金元から0 USDTの取引が届きました。実は真ん中の32文字がまったく違う偽アドレスです。翌月これを履歴からコピーして2,000 USDTを送れば、全額が攻撃者のものになり、取り戻せません。","mistakes":["取引履歴に表示されたアドレスを、送金先としてそのままコピーすること。","アドレスの先頭4文字と末尾4文字だけを見て確認したつもりになること。","身に覚えのない少額や0の入金を無害だと思って放置すること。"],"faq":[{"q":"0 USDTの入金が届いたのですが危険ですか？","a":"受け取っただけで資産が盗まれることはありません。ただし、アドレスポイズニングの前触れの可能性が高いため、その送金元アドレスを今後絶対に使わないよう注意してください。"},{"q":"アドレスポイズニングを防ぐ一番の方法は何ですか？","a":"検証済みのアドレスをアドレス帳やホワイトリストに登録し、毎回そこから送金先を選ぶことです。履歴からのコピーをやめるだけでも大きく防げます。"}],"title":"アドレスポイズニングとは？手口と誤送金の防ぎ方","description":"アドレスポイズニング（類似アドレス詐欺）の手口、取引履歴に紛れ込む偽アドレスの見抜き方、誤送金を防ぐ具体的な対策を解説します。","related":[["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"ja","term":"トークン承認（Approve・アローワンス）","aka":["アプルーブ","approve","アローワンス","allowance","トークン許可"],"short":"トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。","body":[[["イーサリアム","ethereum"],"系のチェーンでERC20トークンをDEXで交換したり、DeFiに預けたりするとき、最初に「承認（Approve）」の取引が必要になります。これは「このコントラクトは私のUSDCを○○まで動かしてよい」という許可です。"],"多くのアプリは手間を省くため、承認額を無制限にするよう求めます。正規のサービスでも、そのコントラクトに不具合や乗っ取りがあれば、承認済みのトークンを抜かれるリスクがあります。悪意あるコントラクトに承認すれば、なおさら危険です。",["承認は取り消すまで有効です。",["ブロックエクスプローラー","block-explorer"],"の承認確認ツールや",["ウォレット","crypto-wallet"],"の機能で、使っていないサービスへの承認を定期的に取り消しましょう。取り消しにも少額の",["ガス代","gas-fee"],"がかかります。"]],"example":"あなたが500 USDCをDEXでETHに交換するとします。承認画面で無制限ではなく、カスタム額として500 USDCを指定して承認し、その後スワップします。後日そのDEXのコントラクトに問題が起きても、残りの承認額は0なので、ウォレットに残る3,000 USDCは引き出されません。無制限で承認していれば、3,000 USDC全額が危険にさらされていました。","mistakes":["承認画面の金額欄を確認せず、無制限の承認をそのまま許可すること。","一度しか使わないサービスへの承認を、取り消さずに放置すること。","承認は送金ではないから安全だと思い込み、見知らぬサイトで署名すること。"],"faq":[{"q":"承認しただけでトークンは減りますか？","a":"承認した時点ではトークンは動きません。ただし承認したコントラクトは、許可された範囲でいつでもトークンを引き出せる状態になります。"},{"q":"承認を取り消すにはどうすればよいですか？","a":"ブロックエクスプローラーの承認確認ページや承認管理ツールで、対象のコントラクトの承認額を0に戻す取引を送ります。この取引にもガス代が必要です。"}],"title":"トークン承認（Approve）とは？リスクと取り消し方","description":"DeFiで求められるトークン承認（Approve・アローワンス）の意味、無制限承認のリスク、使わない承認を取り消す方法を解説します。","related":[["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"ja","term":"DEX（分散型取引所）","aka":["分散型取引所","DEX","デックス"],"short":"DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。","body":[["Uniswap、PancakeSwap、Raydiumなどが代表的です。多くのDEXは、利用者が預けた資金でつくる",["流動性プール","liquidity-pool"],"と",["AMM（自動マーケットメーカー）","amm"],"の仕組みで価格を決めます。オンチェーンの",["板（オーダーブック）","order-book"],"を使うDEXもあります。"],[["本人確認","kyc"],"や口座開設が不要で、",["ウォレット","crypto-wallet"],"を接続するだけで取引できます。",["上場","token-listing"],"前の新しいトークンも誰でも取引できるため、選択肢が広い反面、詐欺トークンやラグプルも混ざっています。"],"コスト面では、取引手数料に加えてガス代とスリッページがかかります。流動性が少ないトークンほど、注文が大きいと価格が不利に動きます。取引所（CEX）との違いを理解して使い分けましょう。"],"example":"あなたがDEXで1,000 USDCを使ってトークンを買うとします。スワップ手数料が0.3%なら3 USDCが差し引かれます。さらにガス代が2ドル、プールの流動性が薄くて実際の約定価格が表示価格より1%不利だったとすると、実質のコストは3+2+約10で約15ドル、つまり購入額の約1.5%になります。スリッページ許容値を0.5%に設定していれば、この取引は失敗して資金は戻ります（ガス代はかかります）。","mistakes":["トークン名だけで検索し、同名の偽トークンのコントラクトを買ってしまうこと。","スリッページ許容値を大きくしすぎて、不利な価格で約定すること。","ガス代を考慮せず、少額の取引を何度も繰り返すこと。"],"faq":[{"q":"DEXとCEXはどちらが安全ですか？","a":"リスクの種類が違います。DEXは運営者に資産を預けない反面、スマートコントラクトや詐欺トークン、自己管理のリスクがあります。CEXは運営会社の管理と規制に依存します。"},{"q":"DEXで買ったトークンはどこに保管されますか？","a":"接続したあなた自身のウォレットに直接届きます。DEXの運営側がトークンを預かることはありません。"}],"title":"DEX（分散型取引所）とは？仕組みとCEXとの違い","description":"DEX（分散型取引所）の意味、AMMによる価格の決まり方、手数料・ガス代・スリッページなどのコストとCEXとの違いを解説します。","related":[["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["perp-dex","パーペチュアルDEX（オンチェーン無期限先物）","パーペチュアルDEXとは、無期限先物（パーペチュアル）を、自分のウォレットから証拠金を入れてブロックチェーン上で取引できる分散型取引所です。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"ja","term":"フラッシュローン","aka":["flash loan","フラッシュ融資"],"short":"フラッシュローンとは、担保なしで暗号資産を借りられる代わりに、同じトランザクション内で必ず返済しなければならないDeFi特有の借入です。","body":[[["ブロックチェーン","blockchain"],"のトランザクションは、すべての処理が成功するか、すべて取り消されるかのどちらかです。フラッシュローンはこの性質を利用し、借入から返済までを1つのトランザクションにまとめます。返済できなければ、借入そのものがなかったことになります。"],["主な用途は、取引所間の価格差を使った",["アービトラージ","arbitrage"],"、担保の入れ替え、DeFiでの借り換えなどです。",["スマートコントラクト","smart-contract"],"を書ける開発者向けの機能で、一般の利用者が直接使うことは多くありません。"],["一方で、フラッシュローンはDeFiへの攻撃にも使われてきました。巨額の資金を一時的に借りて、",["流動性","liquidity"],"の薄い",["プール","liquidity-pool"],"の価格を操作し、その価格を参照するプロトコルから資金を引き出す手口です。",["オラクル","oracle"],"設計の重要性が注目される理由のひとつです。"]],"example":"あるトークンがDEX Aで1.00ドル、DEX Bで1.02ドルで取引されているとします。100万USDCをフラッシュローンで借り、手数料が仮に0.05%なら500ドルです。Aで100万ドル分を買い、Bで売ると、スリッページがなければ102万ドルになり、返済の100万500ドルを差し引いて約19,500ドルが残ります。実際にはスリッページやガス代で利益は小さくなり、利益が出なければトランザクション全体が失敗します。","mistakes":["担保なしで借りられるので、誰でも簡単に稼げる手段だと思い込むこと。","「フラッシュローンで自動的に稼ぐ」とうたうボットや動画の詐欺に資金を送ること。","フラッシュローン攻撃をフラッシュローン自体の欠陥だと考え、オラクルの問題を見落とすこと。"],"faq":[{"q":"フラッシュローンが返済されないとどうなりますか？","a":"トランザクション全体が取り消され、借入もなかったことになります。貸し手が損をすることはなく、借り手は失敗した取引のガス代だけを支払います。"},{"q":"フラッシュローンは違法ですか？","a":"仕組み自体はDeFiの正規機能です。ただし、価格操作などで他のプロトコルから資金を引き出す行為は、国によっては違法とされる可能性があります。"}],"title":"フラッシュローンとは？仕組みと攻撃に使われる理由","description":"DeFiのフラッシュローンの意味、担保なしで借りられる仕組み、アービトラージの計算例と価格操作攻撃に使われる理由を解説します。","related":[["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。"],["oracle","オラクル（ブロックチェーンオラクル）","オラクルとは、価格や天気、試合結果など、ブロックチェーンの外にあるデータをスマートコントラクトに届ける仕組みのことです。"],["mev","MEV（最大抽出可能価値）","MEV（最大抽出可能価値）とは、ブロックに入れる取引の順番を並べ替えたり、取引を差し込んだりすることで、ブロック生成者や専門のボットが得られる追加の利益のことです。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"ja","term":"ラップトークン（Wrapped Token）","aka":["ラップドトークン","wrapped token","WBTC","WETH"],"short":"ラップトークンとは、ある暗号資産を別のブロックチェーンや規格で使えるようにするため、元の資産を裏付けとして1対1で発行されたトークンです。","body":[["代表例はWBTCで、",["ビットコイン","bitcoin"],"を裏付けに",["イーサリアム","ethereum"],"上のERC20トークンとして発行されています。これにより、BTCの価値をイーサリアムのDeFiで使えるようになります。WETHは、ETHをERC20規格に合わせて包んだもので、DEXなどで扱いやすくするために使われます。"],["ラップトークンの価値は、裏付け資産が実際に保管されていることに依存します。WBTCのように管理者が保管するものは、その管理者の信用やセキュリティに頼ることになります。",["ブリッジ","cross-chain-bridge"],"で発行されるものは、ブリッジのコントラクトの安全性に依存します。"],["同じ銘柄でも、発行元やブリッジが違うと別のトークンになります。取引所に入金する際、対応していない種類のラップトークンを送ると反映されないことがあるため、コントラクト",["アドレス","wallet-address"],"と対応ネットワークを確認しましょう。"]],"example":"あなたが0.5 BTCをWBTCに換え、イーサリアムのレンディングで担保にするとします。BTCが6万ドルなら担保価値は3万ドルです。WBTCは裏付けのBTCと1対1で発行されるため、価格は通常BTCとほぼ同じに動きます。ただし、裏付けの管理に問題が生じてWBTCがBTCより2%安く取引されると、担保価値は2万9,400ドルに下がり、BTCの価格が変わっていなくても清算ラインに近づきます。","mistakes":["ラップトークンを元の資産とまったく同じリスクだと考えること。","ブリッジや発行元の異なる同名トークンを区別せず、取引所に送金すること。","WETHとETHの違いを理解せず、ガス代としてWETHを使おうとすること。"],"faq":[{"q":"ラップトークンは元の資産に戻せますか？","a":"発行元やブリッジを通じて償還すれば戻せます。WETHはコントラクトでいつでもETHに戻せますが、WBTCなどは発行・償還の手続きや手数料が発生します。"},{"q":"ラップトークンの価格が元の資産とずれることはありますか？","a":"通常はほぼ同じですが、裏付けの管理への不安やブリッジのハッキングがあると、元の資産より安く取引されることがあります。"}],"title":"ラップトークンとは？WBTC・WETHの仕組みとリスク","description":"ラップトークン（Wrapped Token）の意味、WBTCやWETHの仕組み、裏付け資産やブリッジへの依存などのリスクを解説します。","related":[["cross-chain-bridge","クロスチェーンブリッジ","クロスチェーンブリッジとは、異なるブロックチェーン間で暗号資産やデータを移動できるようにする仕組みで、たとえばイーサリアムのUSDCをレイヤー2に移すときに使われます。"],["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。"],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"ja","term":"KYC（本人確認）","aka":["本人確認","eKYC","Know Your Customer"],"short":"KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。","body":["KYCは「Know Your Customer（顧客を知る）」の略で、マネーロンダリングやテロ資金供与、なりすましを防ぐために行われます。取引所では、氏名・住所・生年月日の入力、運転免許証やマイナンバーカードなどの身分証の撮影、顔写真や動画によるセルフィー確認が一般的です。スマホで完結する方式はeKYCと呼ばれます。",["多くの国で、登録された",["暗号資産","cryptocurrency"],"取引所にはKYCが法律で義務付けられています。日本では金融庁に登録した",["暗号資産交換業者","vasp"],"が、犯罪収益移転防止法に基づいて本人確認を行います。海外取引所でもKYCのレベルが段階的に分かれていて、完了したレベルによって出金上限や使える機能が変わることがあります。"],"KYCで提出した情報は取引所が保管するため、運営の信頼性やデータ保護の姿勢も確認しておきたいポイントです。また、KYCを装って身分証の画像を送らせる詐欺もあるので、提出先が公式のアプリやサイトであることを必ず確かめてください。"],"example":["ある海外取引所で、KYC未完了だと1日の出金上限が0、基本的なKYC（レベル1）を完了すると1日10,000 ",["USDT","usdt"],"、住所確認まで済ませたレベル2で1日100,000 USDTになる、という段階的な仕組みだったとします。あなたが30,000 USDTを一度に出金したい場合、レベル1では10,000 USDTずつ3日に分ける必要があります。急ぎの出金が予想されるなら、資金を入れる前にレベル2まで済ませておくと、審査に数日かかっても困りません。上限の数字は取引所や国によって異なるので、各取引所の案内で確認しましょう。"],"mistakes":["SNSやメッセージで届いた「KYCの再提出」リンクから、身分証の画像を偽サイトにアップロードしてしまう。","入金してから初めてKYCを始め、審査待ちの間に出金できずに困る。","居住国や氏名を事実と違う内容で登録し、後で出金時の追加審査に通らなくなる。"],"faq":[{"q":"暗号資産取引所でKYCは必須ですか？","a":"日本の登録業者では法律上必須です。海外の取引所でも、出金や先物取引などの主要な機能を使うにはKYCが求められるのが一般的です。"},{"q":"KYCの審査にはどのくらい時間がかかりますか？","a":"eKYCなら数分から1日程度で終わることが多いですが、混雑時や追加書類が必要な場合は数日かかることもあります。"}],"title":"KYCとは？暗号資産取引所の本人確認の意味","description":"KYC（本人確認）の意味、取引所で求められる書類と手順、レベルごとの出金上限の違い、KYCを装った詐欺への注意点を解説します。","related":[["aml","AML（マネーロンダリング対策）","AMLとは、犯罪で得た資金の出どころを隠す行為（マネーロンダリング）を防ぐために、金融機関や暗号資産取引所が行う監視・確認・報告の仕組み全体のことです。"],["travel-rule","トラベルルール","トラベルルールとは、暗号資産を取引所間などで送るときに、送金人と受取人の氏名などの情報を事業者同士で共有することを求める国際的なルールです。"],["no-kyc-exchange","KYC不要の取引所（ノーKYC取引所）","KYC不要の取引所とは、身分証明書による本人確認なしで登録や取引、一定額までの出金ができる暗号資産取引所や交換サービスのことです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"],["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC（本人確認）の仕組みと、身分証は誰に提出すべきか？"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"ja","term":"デモトレード","aka":["デモ取引","模擬取引","ペーパートレード","demo trading"],"short":"デモトレードとは、取引所が用意した仮想資金を使い、実際のお金を使わずに本番とほぼ同じ画面で取引を練習できる機能のことです。","body":[["デモトレードでは、たとえば仮想の10,000 USDTなどが付与され、現物や先物の注文方法、",["レバレッジ","leverage"],"の設定、",["損切り","stop-loss"],"や利確の注文などを練習できます。価格は本番の相場に連動している場合が多く、取引所によって「デモ取引」「模擬取引」「テストネット」などと呼ばれています。"],["特に役立つのは、",["無期限先物（パーペチュアル）","perpetual-futures"],"のように仕組みが複雑な商品を初めて使うときです。証拠金と",["清算価格","liquidation-price"],"の関係、",["資金調達率","funding-rate"],"の支払い、",["分離マージン","isolated-margin"],"とクロスマージンの違いなどを、損失を出さずに体験できます。"],"ただし、デモと本番には違いがあります。デモでは注文が理想的に約定しやすく、スリッページや板の薄さの影響が小さいことがあります。また、実際のお金がかかっていないため、損切りを守るなど感情面の練習にはなりにくい点も覚えておきましょう。"],"example":"あなたがデモ口座で、仮想の1,000 USDTを証拠金にして、BTCを20倍のレバレッジでロングしたとします。ポジションは20,000 USDT分です。BTCが約4.5%下がると、維持証拠金などを考慮して清算価格に達し、証拠金の大部分を失います。デモでこれを経験すると、同じ1,000 USDTでもレバレッジを3倍にすればポジションは3,000 USDTで、清算までの値幅が約30%近くまで広がることを、数字で理解できます。清算価格の正確な計算は取引所の仕様によって異なります。","mistakes":["デモで勝てたので、本番でも同じ結果になると考えて最初から大きな金額で始める。","仮想資金だからと極端なレバレッジばかり試し、本番で使えるリスク管理の練習をしない。","デモと本番で約定やスリッページの条件が違うことを考慮しない。"],"faq":[{"q":"デモトレードで得た利益は引き出せますか？","a":"いいえ、デモトレードの資金は仮想のものなので、利益を引き出すことはできません。練習のための機能です。"},{"q":"デモトレードはどのくらい練習すればよいですか？","a":"決まった期間はありませんが、注文の出し方、損切りの設定、清算価格の確認を迷わずできるようになってから、少額で本番を始めるのが一般的です。"}],"title":"デモトレードとは？仮想資金で練習する方法","description":"デモトレードの意味と使い方、先物やレバレッジを練習するメリット、本番の取引との違いと注意点を具体例で解説します。","related":[["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["copy-trading","コピートレード","コピートレードとは、取引所上で選んだ他のトレーダーの売買を、自分の口座で自動的に同じように再現する仕組みのことです。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10倍レバレッジ：お金が増えるのか、リスクが増えるのか？"},"coin":null,"tool":null,"cta":true}});
